"""APC1 -> OIT conversion engine, adapted from supplied v8 script.
Business rules and embedded OIT2 template are retained.
"""
from io import BytesIO
from datetime import datetime
from zoneinfo import ZoneInfo
import base64
import re

from openpyxl import load_workbook
from openpyxl.styles import Border, Side, PatternFill
from openpyxl.utils import get_column_letter

MAPPED_APC_COLUMNS = {8, 9, 10, 11, 12, 13, 15, 17, 22, 23}
EMBEDDED_OIT_TEMPLATE = """"""


def find_data_sheet(wb):
    req = {
        "Device Category / Feature Group", "Required?", "Selection Type",
        "Device Model Name/ Part Number", "Device Name/Feature Description",
        "Associated Mask Layers", "Is Experimental Device", "RESTRICTED",
        "Group Exclusion", "Comments",
    }
    for ws in wb.worksheets:
        headers = {str(c.value).strip() for c in ws[1] if c.value is not None}
        if req.issubset(headers):
            return ws
    raise ValueError("Expected APC1 headers were not found.")


def normalize_yes_no(v):
    t = str(v or "").strip().casefold()
    return "Yes" if t == "yes" else "No" if t == "no" else str(v or "").strip()


def qualified_from_experimental(v):
    t = str(v or "").strip().casefold()
    return "No" if t == "yes" else "Yes" if t == "no" else ""


def category_range(required_value, selection_value):
    r = str(required_value or "").strip().casefold()
    s = str(selection_value or "").strip().casefold()
    mapping = {
        ("yes", "multi select"): "Include one or any (1-99)",
        ("yes", "single select"): "Must include only one (1-1)",
        ("no", "multi select"): "Include none or any (0-99)",
    }
    return mapping.get((r, s), str(selection_value or "").strip())


def n_a_if_blank(v):
    return "n/a" if v in (None, "") else v


def convert_apc_to_oit(file_bytes: bytes, original_filename: str):
    if not file_bytes:
        raise ValueError("The uploaded APC1 Excel file is empty.")
    try:
        apc_wb = load_workbook(BytesIO(file_bytes), data_only=True)
    except Exception as exc:
        raise ValueError("Cannot open APC1 Excel. Check that it is a valid, unencrypted .xlsx/.xlsm file.") from exc

    apc_ws = find_data_sheet(apc_wb)
    oit_wb = load_workbook(BytesIO(base64.b64decode(EMBEDDED_OIT_TEMPLATE)))
    oit_ws = oit_wb[oit_wb.sheetnames[0]]
    if oit_ws.max_row >= 3:
        oit_ws.delete_rows(3, oit_ws.max_row - 2)
    for sh in list(oit_wb.worksheets):
        if sh is not oit_ws:
            oit_wb.remove(sh)
    oit_ws.title = "OIT_result"

    remaining = [c for c in range(1, apc_ws.max_column + 1) if c not in MAPPED_APC_COLUMNS]
    for oc, sc in enumerate(remaining, 12):
        h = apc_ws.cell(1, sc).value
        oit_ws.cell(2, oc).value = h
        oit_ws.column_dimensions[get_column_letter(oc)].width = max(14, min(35, len(str(h or "")) + 2))

    outrow = 3
    converted = 0
    for sr in range(2, apc_ws.max_row + 1):
        if all(apc_ws.cell(sr, c).value in (None, "") for c in range(1, apc_ws.max_column + 1)):
            continue
        vals = {
            1: apc_ws.cell(sr, 8).value,
            2: category_range(apc_ws.cell(sr, 9).value, apc_ws.cell(sr, 10).value),
            3: "n/a",
            4: apc_ws.cell(sr, 11).value,
            5: apc_ws.cell(sr, 12).value,
            6: n_a_if_blank(apc_ws.cell(sr, 13).value),
            7: normalize_yes_no(apc_ws.cell(sr, 17).value),
            8: qualified_from_experimental(apc_ws.cell(sr, 15).value),
            9: "n/a",
            10: n_a_if_blank(apc_ws.cell(sr, 22).value),
            11: n_a_if_blank(apc_ws.cell(sr, 23).value),
        }
        for c, v in vals.items():
            oit_ws.cell(outrow, c).value = v
        for oc, sc in enumerate(remaining, 12):
            oit_ws.cell(outrow, oc).value = apc_ws.cell(sr, sc).value
        outrow += 1
        converted += 1

    thin = Side(style="thin", color="000000")
    bordered = Border(left=thin, right=thin, top=thin, bottom=thin)
    last = max(2, outrow - 1)
    for row in oit_ws.iter_rows(min_row=2, max_row=last, min_col=1, max_col=11):
        for cell in row:
            cell.border = bordered
    clear_fill, clear_border = PatternFill(fill_type=None), Border()
    if oit_ws.max_column >= 12:
        for row in oit_ws.iter_rows(min_row=1, max_row=last, min_col=12, max_col=oit_ws.max_column):
            for cell in row:
                cell.fill = clear_fill
                cell.border = clear_border
    oit_ws.freeze_panes = "A3"
    oit_ws.auto_filter.ref = f"A2:{get_column_letter(oit_ws.max_column)}{last}"

    mmdd = datetime.now(ZoneInfo("Asia/Singapore")).strftime("%m%d")
    pt = re.search(r"PT\d+", original_filename, re.I)
    output_name = f"{mmdd}_OIT_result_{pt.group(0).upper() if pt else 'PT_UNKNOWN'}.xlsx"
    output = BytesIO()
    oit_wb.save(output)
    apc_wb.close()
    oit_wb.close()
    return output.getvalue(), output_name, converted
